if (session_status() === PHP_SESSION_NONE) session_start();
function ev_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function ev_redirect(array $p):void{header('Location: eval_viewer.php?'.http_build_query($p));exit;}
function ev_is_image($v):bool{$v=trim((string)$v);if($v==='')return false;if(str_starts_with($v,'data:image/'))return true;$path=(string)(parse_url($v,PHP_URL_PATH)??'');return(bool)preg_match('/\.(png|jpe?g|gif|webp|svg)$/i',$path);}
function ev_media($v,string $alt='',string $class='quiz-media'):string{$v=trim((string)$v);if($v==='')return'';return ev_is_image($v)?'<img class="'.ev_h($class).'" src="'.ev_h($v).'" alt="'.ev_h($alt).'" loading="eager">':ev_h($v);}
function ev_unit_questions(PDO $pdo,string $unitId,string $assignmentKey,int $attempt):array{$st=$pdo->prepare('SELECT id,type,unit_id,data FROM activities WHERE unit_id::text=:unit ORDER BY id ASC');$st->execute(['unit'=>$unitId]);$all=[];foreach(($st->fetchAll(PDO::FETCH_ASSOC)?:[])as$a){foreach(qz_normalize_activity($a)as$q){if(($q['type']??'')!=='pronunciation')$all[]=$q;}}return qz_build($all,$unitId,$assignmentKey,$attempt);}
function ev_result_totals(array $quiz,array $answers):array{$s=qz_answers_totals($quiz,$answers);$possible=max(0,(int)($s['possible']??0));$earned=max(0.0,min((float)$possible,(float)($s['earned']??0)));return['correct'=>(int)($s['correct_questions']??0),'total'=>count($quiz),'possible'=>$possible,'earned'=>$earned,'percent'=>$possible>0?(int)round(($earned/$possible)*100):0];}
function ev_identity_filter(string $name,string $school,string $level):array{return['sql'=>"LOWER(student_name)=LOWER(?) AND LOWER(COALESCE(student_doc,''))=LOWER(?) AND LOWER(COALESCE(student_phone,''))=LOWER(?)",'params'=>[$name,$school,$level]];}
$token=trim((string)($_GET['t']??''));$step=trim((string)($_GET['step']??'welcome'));$resultId=max(0,(int)($_GET['rid']??0));$qIndex=max(0,(int)($_GET['q']??0));$isPreview=isset($_GET['preview'])&&$_GET['preview']==='1';$link=null;
if($isPreview){if(empty($_SESSION['admin_logged'])&&empty($_SESSION['academic_logged'])){http_response_code(403);exit('Acceso denegado.');}$examId=max(0,(int)($_GET['exam_id']??0));$st=$pdo->prepare("SELECT e.id AS exam_id,e.title AS exam_title,e.time_limit_min,e.max_attempts,e.instructions,e.cefr_level AS exam_cefr,e.status AS exam_status,e.modalities,e.unit_id AS exam_unit_id,'group' AS link_type,'' AS student_name,'' AS student_doc,'' AS student_phone,'' AS student_email,9999 AS max_uses,0 AS uses_count,NULL AS expires_at FROM eval_exams e WHERE e.id=? LIMIT 1");$st->execute([$examId]);$link=$st->fetch(PDO::FETCH_ASSOC)?:null;if(!$link)exit('Examen no encontrado.');$link['id']=null;$token='PREVIEW_'.$examId;}elseif($token!==''){$st=$pdo->prepare("SELECT l.*,e.title AS exam_title,e.time_limit_min,e.max_attempts,e.instructions,e.cefr_level AS exam_cefr,e.status AS exam_status,e.modalities,e.unit_id AS exam_unit_id FROM eval_links l JOIN eval_exams e ON e.id=l.exam_id WHERE l.token=? AND (l.expires_at IS NULL OR l.expires_at>NOW()) LIMIT 1");$st->execute([$token]);$link=$st->fetch(PDO::FETCH_ASSOC)?:null;}
if(!$link){http_response_code(404);exit('<!doctype html><html><body style="font-family:Arial;text-align:center;padding:60px;background:#fff8e8"><h1>Link inválido o expirado</h1><p>Solicita un nuevo enlace a la institución.</p></body></html>');}
$examId=(int)$link['exam_id'];$isUnitExam=trim((string)($link['exam_unit_id']??''))!=='';$errorMsg='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['start_exam'])){$studentName=trim((string)($_POST['student_name']??''));$studentSchool=trim((string)($_POST['student_school']??"LET'S INSTITUTE"));$studentLevel=trim((string)($_POST['student_level']??''));if($studentName===''||$studentSchool===''||$studentLevel===''){$errorMsg='Completa nombre, colegio y grado o nivel.';}else{$identity=ev_identity_filter($studentName,$studentSchool,$studentLevel);$hist=$pdo->prepare("SELECT id,status FROM eval_results WHERE exam_id=? AND ".$identity['sql']." AND status IN ('started','submitted')");$hist->execute(array_merge([$examId],$identity['params']));$rows=$hist->fetchAll(PDO::FETCH_ASSOC)?:[];$submitted=0;foreach($rows as$r){if(($r['status']??'')==='submitted')$submitted++;}$attempt=$submitted+1;$hasUsed=false;if(!$isPreview&&!empty($link['id'])){$used=$pdo->prepare("SELECT 1 FROM eval_results WHERE link_id=? AND ".$identity['sql']." LIMIT 1");$used->execute(array_merge([(int)$link['id']],$identity['params']));$hasUsed=(bool)$used->fetchColumn();}if($attempt>(int)($link['max_attempts']??1)){$errorMsg='Ya alcanzaste el número máximo de intentos.';}elseif(!$isPreview&&!$hasUsed&&(int)($link['uses_count']??0)>=(int)($link['max_uses']??1)){$errorMsg='Este enlace alcanzó el número máximo de estudiantes.';}else{$questions=$isUnitExam?ev_unit_questions($pdo,(string)$link['exam_unit_id'],(string)($link['id']??$examId),$attempt):select_exam_questions($pdo,['exam_id'=>$examId,'unit_ids'=>[],'assignment_id'=>(string)($link['id']??$examId),'total_questions'=>20,'quotas'=>DEFAULT_QUOTAS,'skills'=>array_keys(DEFAULT_QUOTAS)],$studentName.'|'.$studentSchool.'|'.$studentLevel,$attempt,[]);$selection=serialize_exam_selection($questions);$st=$pdo->prepare("INSERT INTO eval_results (exam_id,link_id,student_name,student_doc,student_phone,student_email,modality,selection_json,status,started_at) VALUES (?,?,?,?,?,NULL,'online',?,'started',CURRENT_TIMESTAMP) RETURNING id");$st->execute([$examId,$isPreview?null:(int)$link['id'],$studentName,$studentSchool,$studentLevel,$selection]);$newId=(int)$st->fetchColumn();if(!$isPreview&&!empty($link['id'])&&!$hasUsed)$pdo->prepare('UPDATE eval_links SET uses_count=uses_count+1 WHERE id=?')->execute([$link['id']]);ev_redirect(['t'=>$token,'step'=>'quiz','rid'=>$newId,'q'=>0]+($isPreview?['preview'=>1,'exam_id'=>$examId]:[]));}}}
$quiz=[];$resultRow=null;if($resultId>0){$st=$pdo->prepare('SELECT * FROM eval_results WHERE id=? AND exam_id=? LIMIT 1');$st->execute([$resultId,$examId]);$resultRow=$st->fetch(PDO::FETCH_ASSOC)?:null;if($resultRow)$quiz=load_exam_questions_from_selection($pdo,(string)($resultRow['selection_json']??''));}
$sessionKey='eval_answers_'.$resultId;if(!isset($_SESSION[$sessionKey])||!is_array($_SESSION[$sessionKey]))$_SESSION[$sessionKey]=[];$answers=&$_SESSION[$sessionKey];
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['eval_answer'])&&$resultRow&&$resultRow['status']==='started'){$qIndex=max(0,min((int)($_POST['q_index']??0),max(0,count($quiz)-1)));$q=$quiz[$qIndex]??null;if($q){if(isset($_POST['skip']))$given=null;elseif(in_array(($q['type']??''),['match','drag_drop','drag_drop_kids','unscramble'],true))$given=isset($_POST['answer'])&&is_array($_POST['answer'])?$_POST['answer']:[];else$given=trim((string)($_POST['answer']??''));$score=qz_answer_score($q,$given);$answers[$qIndex]=['answer'=>$given,'correct'=>(bool)$score['correct'],'earned'=>(float)$score['earned'],'possible'=>(int)$score['possible'],'skipped'=>isset($_POST['skip'])];}if(count($answers)>=count($quiz))ev_redirect(['t'=>$token,'step'=>'submit','rid'=>$resultId]+($isPreview?['preview'=>1,'exam_id'=>$examId]:[]));ev_redirect(['t'=>$token,'step'=>'quiz','rid'=>$resultId,'q'=>min($qIndex+1,max(0,count($quiz)-1))]+($isPreview?['preview'=>1,'exam_id'=>$examId]:[]));}
if($step==='submit'&&$resultRow&&$resultRow['status']==='started'){$totals=ev_result_totals($quiz,$answers);$log=[];foreach($quiz as$i=>$q){$a=$answers[$i]??['answer'=>null,'correct'=>false,'earned'=>0,'possible'=>qz_answer_score($q,null)['possible']];$log[]=['q'=>$i,'type'=>$q['type']??'','given'=>is_array($a['answer'])?json_encode($a['answer']):(string)($a['answer']??''),'correct'=>qz_review_correct_text($q),'is_correct'=>(bool)$a['correct'],'pts_earned'=>(float)$a['earned'],'pts_max'=>(int)$a['possible']];}$pdo->prepare("UPDATE eval_results SET score=?,max_score=?,pct=?,answers_json=?,status='submitted',submitted_at=CURRENT_TIMESTAMP WHERE id=?")->execute([$totals['earned'],$totals['possible'],$totals['percent'],json_encode($log),$resultId]);unset($_SESSION[$sessionKey]);ev_redirect(['t'=>$token,'step'=>'result','rid'=>$resultId]+($isPreview?['preview'=>1,'exam_id'=>$examId]:[]));}
$attemptsUsed=0;$canRetake=false;if($step==='result'&&$resultRow){$st=$pdo->prepare('SELECT * FROM eval_results WHERE id=? LIMIT 1');$st->execute([$resultId]);$resultRow=$st->fetch(PDO::FETCH_ASSOC)?:$resultRow;$identity=ev_identity_filter((string)($resultRow['student_name']??''),(string)($resultRow['student_doc']??''),(string)($resultRow['student_phone']??''));$a=$pdo->prepare("SELECT COUNT(*) FROM eval_results WHERE exam_id=? AND ".$identity['sql']." AND status='submitted'");$a->execute(array_merge([$examId],$identity['params']));$attemptsUsed=(int)$a->fetchColumn();$canRetake=!$isPreview&&$attemptsUsed<(int)($link['max_attempts']??1);}
$currentQuestion=$quiz[$qIndex]??null;$timeLimit=(int)($link['time_limit_min']??50);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=ev_h($link['exam_title'])?> — ONES</title><style>:root{--purple:#7F77DD;--orange:#F97316;--line:#EDE9FA;--ink:#14113A;--muted:#8178B6;--bg:#F8F7FF}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Nunito,Arial,sans-serif;color:var(--ink)}.page{max-width:820px;margin:auto;padding:28px 18px 50px}.top,.card{background:#fff;border:1px solid var(--line);border-radius:24px;box-shadow:0 8px 28px rgba(127,119,221,.10)}.top{padding:16px 20px;margin-bottom:18px;display:flex;justify-content:space-between}.brand{font-weight:900;color:var(--purple)}.card{padding:28px}.kicker{display:inline-block;background:#FFF0E6;color:#C2580A;border-radius:999px;padding:6px 13px;font-size:12px;font-weight:900}.title{font-size:34px;color:var(--orange);margin:12px 0}.lead{color:var(--muted);font-weight:700}.chips,.actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.chip{background:#F0EEF8;color:var(--purple);border-radius:999px;padding:7px 11px;font-size:12px;font-weight:900}.input,.select{width:100%;padding:14px;border:1px solid var(--line);border-radius:12px;font:700 16px Nunito,Arial;margin:8px 0}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:12px;padding:12px 18px;background:var(--purple);color:#fff;font-weight:900;text-decoration:none;cursor:pointer}.btn.orange{background:var(--orange)}.btn.light{background:#fff;color:var(--purple);border:1px solid var(--line)}.w100{width:100%}.actions>*{flex:1;min-width:150px}.progress{height:9px;background:#EEEAF9;border-radius:999px;overflow:hidden;margin:10px 0 22px}.progress>div{height:100%;background:linear-gradient(90deg,var(--orange),var(--purple))}.question{font-size:23px;font-weight:900;margin:12px 0}.option{display:flex;align-items:center;gap:12px;padding:14px;border:1px solid var(--line);border-radius:14px;margin:10px 0;font-weight:800}.quiz-media,.option-image{display:block;max-width:100%;max-height:220px;object-fit:contain;margin:auto}.match-row{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:8px 0}.result{font-size:58px;font-weight:900;color:var(--orange);text-align:center}.error{background:#fff1f1;color:#991b1b;border:1px solid #fecaca;border-radius:12px;padding:10px 14px;font-weight:800;margin-bottom:16px}@media(max-width:650px){.actions{flex-direction:column}.match-row{grid-template-columns:1fr}}</style></head><body><div class="page"><div class="top"><div class="brand">ONES · Unit Exam</div><div><?=ev_h($link['exam_title'])?></div></div>
<?php if($step==='welcome'):?><section class="card"><span class="kicker">UNIT EXAM</span><h1 class="title"><?=ev_h($link['exam_title'])?></h1><p class="lead">Enter your information to begin.</p><div class="chips"><span class="chip"><?=$timeLimit?> minutes</span><span class="chip"><?=(int)($link['max_attempts']??1)?> attempt(s)</span></div><?php if($errorMsg):?><div class="error"><?=ev_h($errorMsg)?></div><?php endif;?><form method="post"><input type="hidden" name="start_exam" value="1"><input class="input" name="student_name" required placeholder="Full name"><input class="input" name="student_school" required placeholder="School" value="LET'S INSTITUTE"><input class="input" name="student_level" required placeholder="Grade or level"><button class="btn orange w100" type="submit">Start exam</button></form></section>
<?php elseif($step==='quiz'&&$currentQuestion):?><section class="card"><span class="kicker">QUESTION <?=$qIndex+1?> OF <?=count($quiz)?></span><div class="progress"><div style="width:<?=(int)round((($qIndex+1)/max(1,count($quiz)))*100)?>%"></div></div><div class="question"><?=ev_h($currentQuestion['question']??$currentQuestion['text']??'Answer the question.')?></div><?php if(!empty($currentQuestion['image'])):?><div><?=ev_media($currentQuestion['image'],'Question image')?></div><?php endif;?><form method="post"><input type="hidden" name="eval_answer" value="1"><input type="hidden" name="q_index" value="<?=$qIndex?>"><?php if(($currentQuestion['type']??'')==='multiple_choice'):foreach(($currentQuestion['options']??[])as$i=>$o):?><label class="option"><input type="radio" name="answer" value="<?=$i?>" required><span><?=chr(65+$i)?>.</span><span><?=ev_is_image($o)?ev_media($o,'Option','option-image'):ev_h($o)?></span></label><?php endforeach;elseif(($currentQuestion['type']??'')==='match'):$rights=array_column($currentQuestion['pairs']??[],'right');foreach(($currentQuestion['pairs']??[])as$i=>$p):?><div class="match-row"><strong><?=ev_h($p['left']??'')?></strong><select class="select" name="answer[<?=$i?>]" required><option value="">Choose</option><?php foreach($rights as$r):?><option value="<?=ev_h($r)?>"><?=ev_h($r)?></option><?php endforeach;?></select></div><?php endforeach;elseif(($currentQuestion['type']??'')==='dictation'):?><button class="btn" type="button" onclick="speechSynthesis.speak(new SpeechSynthesisUtterance(<?=json_encode((string)($currentQuestion['correct']??''))?>))">🔊 Listen</button><input class="input" name="answer" required><?php elseif(($currentQuestion['type']??'')==='fill'):?><input class="input" name="answer" required><?php else:?><textarea class="input" name="answer" rows="3" required></textarea><?php endif;?><div class="actions"><button class="btn orange" type="submit">Next</button><button class="btn light" type="submit" name="skip" value="1" formnovalidate>Skip</button></div></form></section>
<?php elseif($step==='result'&&$resultRow):?><section class="card"><span class="kicker">EXAM COMPLETE</span><div class="result"><?=(int)round((float)($resultRow['pct']??0))?>%</div><h1 class="title" style="text-align:center"><?=ev_h($link['exam_title'])?></h1><div class="chips" style="justify-content:center"><span class="chip">Score <?=ev_h($resultRow['score']??0)?> / <?=ev_h($resultRow['max_score']??0)?></span><span class="chip">Attempt <?=$attemptsUsed?> / <?=(int)($link['max_attempts']??1)?></span></div><div class="actions"><?php if($canRetake):?><a class="btn orange" href="eval_viewer.php?<?=ev_h(http_build_query(['t'=>$token,'step'=>'welcome']))?>">Take again</a><?php endif;?><button class="btn light" type="button" onclick="window.close();history.length>1&&history.back();">Close</button></div></section><?php else:?><section class="card"><h1 class="title">Exam unavailable</h1></section><?php endif;?></div></body></html>